function LadderStruggleFormationTeamGroup:CleanProperties()
    self.data = nil
    self.TeamCellLTList = nil
    self.systemName = nil
    self.component = nil
end

function LadderStruggleFormationTeamGroup:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

function LadderStruggleFormationTeamGroup:InitComponent()
    self.TeamCellLTList = {}
    local count = self.RT_TeamGroup.transform.childCount
    for i = 1, count, 1 do
        local child = self.RT_TeamGroup:GetChild(i-1)
        local LB_TeamCell = GetLuaBehaviour(child.gameObject, TeamCellLuaPath)
        table.insert(self.TeamCellLTList, LB_TeamCell.Env)
        LB_TeamCell.Env:SetSystem(self.systemName)
    end

    if not IsNull(self.RL_Team) then
        self.RL_Team.OnElementDropped:AddListener(Bind(self, self.OnElementDropped))
        self.RL_Team.OnElementAdded:AddListener(Bind(self, self.OnElementAdd))
    end
end

function LadderStruggleFormationTeamGroup:UpdateTeamGroup(teamGroup)
    if isNull(teamGroup) then return end

    for i, LT_TeamCell in ipairs(self.TeamCellLTList) do
        -- print("[异步PVP] update team", i, LT_TeamCell, table.dump(teamGroup[i]), debug.traceback())
        LT_TeamCell:UpdateTeamInfo(teamGroup[i])
    end
end

function LadderStruggleFormationTeamGroup:SetParameters(canFormation)
    for i, LT_TeamCell in ipairs(self.TeamCellLTList) do
        -- print("[异步PVP] set parameter", i, canFormation, debug.traceback())
        LT_TeamCell:SetParameters(i, canFormation)
    end
end

function LadderStruggleFormationTeamGroup:OnReorderTeam()
    cs_coroutine.start(function()
        cs_coroutine.yield_return(nil)
        local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
        -- 重新排序
        self.TeamCellLTList = {}
        local count = self.RT_TeamGroup.transform.childCount
        for i = 1, count, 1 do
            local child = self.RT_TeamGroup:GetChild(i-1)
            local LB_TeamCell = GetLuaBehaviour(child.gameObject, TeamCellLuaPath)
            -- print("[异步PVP] reorder", LB_TeamCell.Env, LB_TeamCell.Env.cellIndex, LB_TeamCell.Env.teamInfo)
            table.insert(self.TeamCellLTList, LB_TeamCell.Env)
            LB_TeamCell.Env.cellIndex = i
            if isNotNull(LB_TeamCell.Env.teamInfo) then
                teamComponent:SetTeamByQuestId(self.component.questId, LB_TeamCell.Env.teamInfo.cardsInfo, Constants.ChooseCardStatus.Normal, i)
            end
        end
        teamComponent:SetTeamReq(self.component.questId, function() end)
    end)
end

function LadderStruggleFormationTeamGroup:OnElementDropped(e)
    self:OnReorderTeam()
end

function LadderStruggleFormationTeamGroup:OnElementAdd(e)
    -- 排序组件在元素拖动到外面的时候，canceldrag还原位置的时候，index计算有问题
    -- 这里是在canceldrag的时候，也触发一次保存编队，防止界面上顺序变了，但是没有把顺序保存到服务器上
    if e.FromIndex == e.ToIndex then
        self:OnReorderTeam()
    end
end

